import { defineCollection } from 'astro:content';
import { glob } from 'astro/loaders';
import { z } from 'astro/zod';

/** Generated by scripts/gen-problems.mjs — summaries only (FE-13). Never edit by hand. */
const problems = defineCollection({
  loader: glob({ base: './src/content/problems', pattern: '*.md' }),
  schema: z.object({
    slug: z.string(),
    title: z.string(),
    track: z.enum(['algorithms', 'database', 'refactoring', 'architecture', 'secureCoding', 'testWriting']),
    difficulty: z.enum(['easy', 'medium', 'hard']),
    free: z.boolean(),
    sortOrder: z.number().int(),
    tags: z.array(z.string()),
    limits: z.object({ timeoutSeconds: z.number(), memoryMb: z.number() }),
    visibleTestCount: z.number().int(),
    hiddenTestCount: z.number().int(),
  }),
});

const blog = defineCollection({
  loader: glob({ base: './src/content/blog', pattern: '**/*.{md,mdx}' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    pubDate: z.coerce.date(),
    tags: z.array(z.string()).default([]),
    draft: z.boolean().default(false),
  }),
});

export const collections = { problems, blog };
